        "everyday|5:1|5|q0o1": "1박",
        "everyday|5:1|5|q0o2": "2박",
        "everyday|5:1|5|q0o3": "5박",
        "everyday|5:1|5|q1": "라훌은 왜 엘리베이터에서 먼 방을 원하나요?",
