        "everyday|6:1|0|w3": "좌석 예약",
        "everyday|6:1|0|w4": "요금",
        "everyday|6:1|0|w5": "객차",
        "everyday|6:1|1|p0": "찰루키아 익스프레스는 몇 번 승강장에서 출발해요?",
        "everyday|6:1|1|p1": "아버지가 위로 올라가기 힘드셔서 아래쪽 침대석이 좋겠어요.",
        "everyday|6:1|1|p2": "우리 표가 아직 대기자 명단에 있어서 자리를 못 받을 수도 있어요.",
        "everyday|6:1|1|p3": "디왈리 최소 한 달 전에는 좌석을 예약해야 해요.",
        "everyday|6:1|1|p4": "푸네까지 가는 침대 객차 요금은 600루피 정도예요.",
        "everyday|6:1|2|w0": "지연",
        "everyday|6:1|2|w1": "취소",
        "everyday|6:1|2|w2": "문의",
        "everyday|6:1|2|w3": "짐",
        "everyday|6:1|2|w4": "시간표",
        "everyday|6:1|2|w5": "짐꾼",
        "everyday|6:1|3|p0": "델리 근처의 짙은 안개 때문에 4시간 지연되고 있어요.",
        "everyday|6:1|3|p1": "이틀 전보다 일찍 취소하면 취소 수수료가 적어요.",
        "everyday|6:1|3|p2": "버스가 취소돼서 환불을 요청하러 문의 창구에 갔어요.",
        "everyday|6:1|3|p3": "방금 안내 방송 들었어요? 짐을 5번 승강장까지 옮겨야 해요.",
        "everyday|6:1|3|p4": "시간표에 따르면 마이수루행 막차는 10시에 출발해요.",
        "everyday|6:1|4|title": "가까스로 제시간에",
        "everyday|6:1|4|text": "아샤는 언니의 결혼식에 가려고 후발리에서 푸네로 가고 있었어요. 두 달 전에 좌석을 예약해 두어서 S4 객차의 아래쪽 침대석이 있었어요. 역에서 기차가 3시간 지연된다는 안내 방송이 나왔어요. 아샤는 휴대폰으로 버스 시간표를 확인하고 푸네에 더 빨리 도착하는 버스를 찾았어요. 기차표는 온라인으로 취소했고, 환불금은 이틀 만에 계좌로 들어왔어요. 짐꾼이 적은 돈을 받고 무거운 가방들을 버스 정류장까지 옮겨 주었어요. 아샤는 메헨디 행사에 딱 맞춰 푸네에 도착했어요.",
        "everyday|6:1|4|q0": "아샤는 왜 푸네에 가고 있었나요?",
        "everyday|6:1|4|q0o0": "언니의 결혼식 때문에",
        "everyday|6:1|4|q0o1": "취업 면접 때문에",
        "everyday|6:1|4|q0o2": "대학 여행 때문에",
        "everyday|6:1|4|q0o3": "병원에 가려고",
        "everyday|6:1|4|q1": "기차는 얼마나 지연되었나요?",
        "everyday|6:1|4|q1o0": "3시간",
        "everyday|6:1|4|q1o1": "30분",
        "everyday|6:1|4|q1o2": "1시간",
        "everyday|6:1|4|q1o3": "하루 종일",
        "everyday|6:1|4|q2": "아샤는 결국 어떻게 푸네에 갔나요?",
        "everyday|6:1|4|q2o0": "버스로",
        "everyday|6:1|4|q2o1": "나중 기차로",
        "everyday|6:1|4|q2o2": "비행기로",
        "everyday|6:1|4|q2o3": "택시로",
        "everyday|6:1|5|title": "취소된 기차",
        "everyday|6:1|5|scenario": "마이수루 기차역에서 카비타는 벵갈루루행 기차가 취소된 것을 알고, 문의 창구의 수레시에게 도움을 요청해요.",
        "everyday|6:1|5|l0": "실례합니다. 방금 차문디 익스프레스가 취소됐다는 안내 방송을 들었는데, 맞나요?",
        "everyday|6:1|5|l1": "안타깝게도 그렇습니다, 손님. 만디아 근처 선로에 문제가 생겼어요.",
        "everyday|6:1|5|l2": "이런. 벵갈루루에서 2시에 중요한 회의가 있어요. 어떤 방법이 있을까요?",
        "everyday|6:1|5|l3": "3번 승강장에서 11시 15분에 출발하는 급행열차가 있어요. 보통 1시 반쯤 도착해요.",
        "everyday|6:1|5|l4": "그 기차에 남은 자리가 있나요?",
        "everyday|6:1|5|l5": "죄송하지만 일반 객차만 있어요. 지정석은 전부 대기자 명단에 있어요.",
        "everyday|6:1|5|l6": "일반 객차도 괜찮아요. 그럼 취소된 제 표는 어떻게 되나요?",
        "everyday|6:1|5|l7": "철도청에서 기차를 취소했으니까 일주일 안에 전액 환불받으실 거예요.",
        "everyday|6:1|5|l8": "환불받으려면 신청서를 작성해야 하나요?",
        "everyday|6:1|5|l9": "아니요, 손님. 온라인으로 예매하셔서 자동으로 처리돼요. 안전한 여행 되세요.",
        "everyday|6:1|5|q0": "차문디 익스프레스는 왜 취소되었나요?",
        "everyday|6:1|5|q0o0": "만디아 근처 선로 문제",
        "everyday|6:1|5|q0o1": "마이수루의 폭우",
        "everyday|6:1|5|q0o2": "직원들의 파업",
        "everyday|6:1|5|q0o3": "승객이 너무 적어서",
        "everyday|6:1|5|q1": "수레시는 어떤 기차를 권하나요?",
        "everyday|6:1|5|q1o0": "11시 15분 급행열차",
        "everyday|6:1|5|q1o1": "야간열차",
