        "services|1:1|0|w0": "약국",
        "services|1:1|0|w1": "약사",
        "services|1:1|0|w2": "알약",
        "services|1:1|0|w3": "시럽",
        "services|1:1|0|w4": "복용량",
        "services|1:1|0|w5": "부작용",
        "services|1:1|1|p0": "이 근처에 밤새 문을 여는 약국이 있나요?",
        "services|1:1|1|p1": "열 살 아이에게 맞는 복용량을 알려 주시겠어요?",
        "services|1:1|1|p2": "약사가 매 식사 후에 알약을 한 알씩 먹으라고 했어요.",
        "services|1:1|1|p3": "이 기침 시럽은 졸음 같은 부작용이 있나요?",
        "services|1:1|1|p4": "죄송하지만, 처방전 없이는 이 약을 드릴 수 없어요.",
        "services|1:1|2|w0": "연고",
        "services|1:1|2|w1": "알레르기",
        "services|1:1|2|w2": "유통기한",
        "services|1:1|2|w3": "진통제",
        "services|1:1|2|w4": "항생제",
        "services|1:1|2|w5": "졸린",
        "services|1:1|3|p0": "이 연고를 하루에 두 번 덴 곳에 살살 발라 주세요.",
        "services|1:1|3|p1": "페니실린 알레르기가 있으니까 다른 약을 추천해 주세요.",
        "services|1:1|3|p2": "새 약 한 판을 뜯기 전에 항상 유통기한을 확인하세요.",
        "services|1:1|3|p3": "몸이 좀 나아져도 항생제는 끝까지 다 드세요.",
        "services|1:1|3|p4": "이 진통제를 먹으면 졸릴 수 있으니까 먹은 후에는 운전하지 마세요.",
        "services|1:1|4|title": "늦은 밤의 약국",
        "services|1:1|4|text": "마이수루의 어느 날 밤 10시, 미라의 어린 남동생 로한이 고열 때문에 잠에서 깼어요. 가족 주치의는 다른 지역에 가 있어서, 미라는 의사에게 전화로 조언을 구했어요. 의사는 아침까지는 해열 시럽이면 충분하다고 했어요. 미라는 버스 터미널 근처에서 밤새 문을 여는 약국을 찾았어요. 미라는 약사에게 로한이 여덟 살이고 어떤 항생제에 알레르기가 있다고 말했어요. 약사는 유통기한을 확인하고, 상자에 복용량을 적은 다음, 시럽 때문에 로한이 졸릴 수 있다고 주의를 주었어요. 아침이 되자 로한의 열은 내렸고, 로한은 도사를 먹고 싶다고 했어요.",
        "services|1:1|4|q0": "미라는 왜 밤에 약국에 갔나요?",
        "services|1:1|4|q0o0": "로한이 고열이 났어요",
        "services|1:1|4|q0o1": "새 휴대폰 충전기가 필요했어요",
        "services|1:1|4|q0o2": "로한이 손을 데었어요",
        "services|1:1|4|q0o3": "의사가 비타민을 사 오라고 했어요",
        "services|1:1|4|q1": "약사는 상자에 무엇을 적었나요?",
        "services|1:1|4|q1o0": "복용량",
        "services|1:1|4|q1o1": "가격",
        "services|1:1|4|q1o2": "로한의 이름",
        "services|1:1|4|q1o3": "의사의 전화번호",
        "services|1:1|4|q2": "아침에 로한은 어땠나요?",
        "services|1:1|4|q2o0": "열이 내렸어요",
        "services|1:1|4|q2o1": "병원에 가야 했어요",
        "services|1:1|4|q2o2": "여전히 많이 아팠어요",
        "services|1:1|4|q2o3": "새로운 알레르기가 생겼어요",
        "services|1:1|5|title": "약사에게 물어보기",
        "services|1:1|5|scenario": "키란은 심한 감기에 걸려서 후발리의 약사 라타에게 조언을 구해요.",
        "services|1:1|5|l0": "안녕하세요. 무엇을 도와드릴까요?",
        "services|1:1|5|l1": "안녕하세요. 어제부터 코가 막히고 목이 아파요. 약 좀 추천해 주시겠어요?",
        "services|1:1|5|l2": "열이 있거나 약물 알레르기가 있으세요?",
        "services|1:1|5|l3": "열은 없고, 제가 알기로는 알레르기도 없어요. 너무 독한 약은 먹고 싶지 않아요.",
        "services|1:1|5|l4": "그럼 이 감기약을 드세요. 아침에 한 알, 밤에 한 알, 식후에 드시면 돼요.",
        "services|1:1|5|l5": "제가 알아야 할 부작용이 있나요?",
        "services|1:1|5|l6": "조금 졸릴 수 있으니까 밤에 드신 후에는 운전하지 마세요.",
        "services|1:1|5|l7": "알겠어요. 그리고 목에 좋은 약도 있을까요?",
        "services|1:1|5|l8": "이 시럽이 도움이 될 거예요. 하루에 세 번, 두 숟가락씩 드세요. 사흘 안에 낫지 않으면 꼭 병원에 가 보세요.",
        "services|1:1|5|l9": "정말 도움이 됐어요, 감사합니다. UPI로 계산해도 되나요?",
        "services|1:1|5|q0": "키란은 알약을 얼마나 자주 먹어야 하나요?",
        "services|1:1|5|q0o0": "하루에 두 번, 식후에",
        "services|1:1|5|q0o1": "일주일에 한 번",
        "services|1:1|5|q0o2": "한 시간마다",
        "services|1:1|5|q0o3": "열이 날 때만",
        "services|1:1|5|q1": "라타는 어떤 부작용에 대해 주의를 주었나요?",
        "services|1:1|5|q1o0": "졸음",
