        "services|2:1|0|w3": "소방대",
        "services|2:1|0|w4": "사고",
        "services|2:1|0|w5": "랜드마크",
        "services|2:1|1|p0": "후발리 버스 터미널 근처에서 난 교통사고를 신고하려고요.",
        "services|2:1|1|p1": "구급차 좀 빨리 보내 주세요. 남자가 길에 쓰러져 있어요.",
        "services|2:1|1|p2": "응급 상황에서는 112 긴급 전화로 전화해서 천천히 또박또박 말하세요.",
        "services|2:1|1|p3": "소방대가 오고 있으니까 지금 바로 건물에서 나가세요.",
        "services|2:1|1|p4": "가장 가까운 랜드마크는 주유소 맞은편에 있는 큰 사원이에요.",
        "services|2:1|2|w0": "다친",
