        "services|2:1|2|w3": "응급 처치",
        "services|2:1|2|w4": "도난",
        "services|2:1|2|w5": "당황",
        "services|2:1|3|p0": "두 명이 다쳤고, 그중 한 명은 의식이 없어요.",
        "services|2:1|3|p1": "출혈을 멈추려면 깨끗한 천으로 상처를 눌러 주세요.",
        "services|2:1|3|p2": "응급 처치 할 줄 아세요, 아니면 구급차를 기다려야 할까요?",
        "services|2:1|3|p3": "역에서 가방을 도난당해서 도난 신고를 해야 해요.",
        "services|2:1|3|p4": "당황하지 마시고, 숨을 깊이 쉬고 주소를 말씀해 주세요.",
        "services|2:1|4|title": "고속도로 위의 도움",
        "services|2:1|4|text": "라비는 망갈루루에서 우두피로 운전하던 중 고속도로 옆에 오토바이가 쓰러져 있는 것을 보았어요. 한 젊은 남자가 그 옆에 앉아 있었는데, 팔에서 피가 많이 나고 있었어요. 라비는 차를 세우고 당황하지 말자고 스스로에게 말했어요. 그는 108에 전화해서 \"사고를 신고하려고요. 한 명이 다쳤어요.\"라고 말했어요. 상담원이 정확한 위치를 물어서, 라비는 가장 가까운 랜드마크인 수라트칼 등대를 알려 주었어요. 기다리는 동안 라비는 깨끗한 수건으로 상처를 눌러 응급 처치를 했어요. 구급차는 15분 만에 도착했고, 나중에 그 젊은 남자는 침착하게 곁에 있어 준 라비에게 고마워했어요.",
        "services|2:1|4|q0": "라비는 어디에서 오토바이를 보았나요?",
        "services|2:1|4|q0o0": "고속도로 옆",
        "services|2:1|4|q0o1": "병원 밖",
        "services|2:1|4|q0o2": "우두피의 주차장",
        "services|2:1|4|q0o3": "망갈루루의 집 근처",
        "services|2:1|4|q1": "라비는 어떤 랜드마크를 알려 주었나요?",
        "services|2:1|4|q1o0": "수라트칼 등대",
        "services|2:1|4|q1o1": "주유소",
        "services|2:1|4|q1o2": "우두피 사원",
        "services|2:1|4|q1o3": "버스 터미널",
        "services|2:1|4|q2": "구급차가 도착하는 데 얼마나 걸렸나요?",
        "services|2:1|4|q2o0": "15분",
        "services|2:1|4|q2o1": "1시간",
        "services|2:1|4|q2o2": "5분",
        "services|2:1|4|q2o3": "30분",
        "services|2:1|5|title": "112에 전화하기",
        "services|2:1|5|scenario": "난디니는 푸네의 자기 골목에 있는 집에서 연기가 나는 것을 보고 112 긴급 전화에 전화해요. 수레시가 전화를 받아요.",
        "services|2:1|5|l0": "112 긴급 전화입니다. 무슨 일이세요?",
        "services|2:1|5|l1": "우리 동네 집에 불이 났어요. 위층 창문에서 짙은 연기가 나오는 게 보여요.",
        "services|2:1|5|l2": "진정하세요. 집 안에 아직 사람이 있나요?",
        "services|2:1|5|l3": "잘 모르겠어요. 노부부가 사시는데, 밖에서는 안 보여요.",
        "services|2:1|5|l4": "지금 바로 소방대와 구급차를 보내겠습니다. 정확한 주소가 어떻게 되나요?",
        "services|2:1|5|l5": "코트루드, 샨티 나가르 14번지예요. 모퉁이에 있는 파란 물탱크가 랜드마크예요.",
        "services|2:1|5|l6": "감사합니다. 절대 안으로 들어가지 마시고, 다른 사람들도 연기에서 멀리 떨어지게 해 주세요.",
        "services|2:1|5|l7": "알겠어요. 아, 이웃 말로는 노부부가 사원에 가셔서 집이 비어 있대요.",
        "services|2:1|5|l8": "다행이네요. 소방대가 10분쯤 후에 도착할 거예요. 전화 끊지 말고 기다려 주세요.",
        "services|2:1|5|l9": "정말 고맙습니다. 벌써 사이렌 소리가 들려요.",
        "services|2:1|5|q0": "난디니는 왜 112에 전화했나요?",
        "services|2:1|5|q0o0": "어느 집에서 연기가 나는 걸 봤어요",
        "services|2:1|5|q0o1": "교통사고를 봤어요",
        "services|2:1|5|q0o2": "휴대폰을 도둑맞았어요",
        "services|2:1|5|q0o3": "어머니가 편찮으셨어요",
        "services|2:1|5|q1": "난디니는 어떤 랜드마크를 알려 주었나요?",
        "services|2:1|5|q1o0": "모퉁이의 파란 물탱크",
        "services|2:1|5|q1o1": "큰 사원",
        "services|2:1|5|q1o2": "주유소",
        "services|2:1|5|q1o3": "기차역",
        "services|2:1|5|q2": "노부부는 어디에 있었나요?",
        "services|2:1|5|q2o0": "사원에",
        "services|2:1|5|q2o1": "집 안에",
        "services|2:1|5|q2o2": "병원에",
