        "services|3:1|0|w0": "배관공",
        "services|3:1|0|w1": "전기 기사",
        "services|3:1|0|w2": "누수",
        "services|3:1|0|w3": "수도꼭지",
        "services|3:1|0|w4": "배선",
        "services|3:1|0|w5": "퓨즈",
        "services|3:1|1|p0": "부엌 수도꼭지에서 밤새 물이 똑똑 떨어졌어요. 오늘 배관공을 보내 주실 수 있나요?",
        "services|3:1|1|p1": "욕실 세면대 밑에서 물이 새서 바닥이 항상 젖어 있어요.",
        "services|3:1|1|p2": "온수기를 켤 때마다 퓨즈가 나가요.",
        "services|3:1|1|p3": "전기 기사님 말로는 이 집의 오래된 배선이 안전하지 않대요.",
        "services|3:1|1|p4": "전선을 만지기 전에 메인 스위치를 꼭 내려 주세요.",
        "services|3:1|2|w0": "가전제품",
        "services|3:1|2|w1": "고장",
        "services|3:1|2|w2": "수리 기사",
        "services|3:1|2|w3": "교체 부품",
        "services|3:1|2|w4": "견적",
        "services|3:1|2|w5": "출장비",
        "services|3:1|3|p0": "세탁기가 고장 났어요. 빨래할 때마다 중간에 멈춰요.",
        "services|3:1|3|p1": "수리 기사님이 내일 아침 제가 출근하기 전에 오실 수 있을까요?",
        "services|3:1|3|p2": "시작하기 전에 전체 비용 견적을 알려 주실 수 있나요?",
        "services|3:1|3|p3": "교체 부품이 벵갈루루에서 오는 데 사흘 걸릴 거예요.",
        "services|3:1|3|p4": "대형 가전제품은 출장비가 1회 방문에 300루피예요.",
        "services|3:1|4|title": "차가워지지 않는 냉장고",
        "services|3:1|4|text": "칼라부라기의 무더운 5월 어느 주, 쿨카르니 가족의 냉장고가 갑자기 차가워지지 않았어요. 수니타는 회사 서비스 센터에 전화해서 불은 켜지는데 안이 따뜻하다고 고장 증상을 분명하게 설명했어요. 다음 날 오후에 수리 기사가 와서 냉장고를 꼼꼼하게 점검했어요. 기사는 냉각 장치의 부품 하나가 고장 나서 교체해야 한다고 했어요. 수리를 시작하기 전에 수니타가 정중하게 견적을 물어보자, 기사는 출장비를 포함해서 총 2,000루피 정도라고 했어요. 부품은 이틀 뒤에 후발리에서 도착했고, 기사는 한 시간 만에 냉장고를 고쳤어요. 그날 저녁 냉장고는 다시 차가워졌고, 가족은 드디어 우유와 요거트를 보관할 수 있었어요.",
        "services|3:1|4|q0": "냉장고에 무슨 문제가 있었나요?",
        "services|3:1|4|q0o0": "차가워지지 않았어요",
        "services|3:1|4|q0o1": "문이 부서졌어요",
        "services|3:1|4|q0o2": "큰 소리가 났어요",
        "services|3:1|4|q0o3": "불이 안 켜졌어요",
        "services|3:1|4|q1": "수니타는 작업이 시작되기 전에 무엇을 요청했나요?",
        "services|3:1|4|q1o0": "비용 견적",
        "services|3:1|4|q1o1": "새 냉장고",
        "services|3:1|4|q1o2": "요금 할인",
        "services|3:1|4|q1o3": "회사 매니저의 전화번호",
        "services|3:1|4|q2": "부품은 어디에서 왔나요?",
        "services|3:1|4|q2o0": "후발리",
        "services|3:1|4|q2o1": "벵갈루루",
        "services|3:1|4|q2o2": "마이수루",
        "services|3:1|4|q2o3": "푸네",
        "services|3:1|5|title": "전기 기사 부르기",
        "services|3:1|5|scenario": "파르한은 집의 퓨즈가 자꾸 나가서, 마이수루에서 집수리 서비스를 운영하는 아샤에게 전화해요.",
        "services|3:1|5|l0": "안녕하세요, 퀵픽스 홈 서비스의 아샤입니다. 무엇을 도와드릴까요?",
        "services|3:1|5|l1": "안녕하세요, 전기 문제 때문에 전화드렸어요. 집 퓨즈가 자꾸 나가는데, 주로 저녁에 그래요.",
        "services|3:1|5|l2": "그렇군요. 특정 가전제품을 켤 때 그런가요?",
        "services|3:1|5|l3": "그런 것 같아요. 보통 온수기와 다리미를 같이 켜면 그래요.",
        "services|3:1|5|l4": "배선에 문제가 있을 수도 있어요. 전기 기사를 보내서 점검해 드릴 수 있어요. 언제가 편하세요?",
        "services|3:1|5|l5": "오늘 와 주실 수 있나요? 6시까지 집에서 재택근무를 하거든요.",
        "services|3:1|5|l6": "저희 전기 기사 마헤시가 4시에 갈 수 있어요. 방문 출장비는 250루피예요.",
        "services|3:1|5|l7": "좋아요. 수리를 시작하기 전에 견적을 알려 주실까요?",
        "services|3:1|5|l8": "네, 항상 비용부터 먼저 설명해 드려요. 주소는 왓츠앱으로 보내 주세요.",
        "services|3:1|5|l9": "좋아요, 지금 바로 보낼게요. 감사합니다.",
        "services|3:1|5|q0": "파르한의 집에는 무슨 문제가 있나요?",
        "services|3:1|5|q0o0": "퓨즈가 자꾸 나가요",
        "services|3:1|5|q0o1": "수도꼭지에서 물이 새요",
        "services|3:1|5|q0o2": "냉장고가 차가워지지 않아요",
        "services|3:1|5|q0o3": "문 잠금장치가 고장 났어요",
        "services|3:1|5|q1": "전기 기사는 몇 시에 오나요?",
        "services|3:1|5|q1o0": "4시에",
        "services|3:1|5|q1o1": "6시에",
